def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.154.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.153.0"' not in init:
        sys.exit("ABORT: not at v3.153.0.")
    if "pos_profile" not in data:
        sys.exit("ABORT: pos_profile module not found in data file.")

    problems = []
    if len(LESSONS) != 10:
        problems.append(f"  {len(LESSONS)} lessons (want 10)")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in LESSONS if len(l["html"]) < 2500]
    if short:
        problems.append(f"  below depth: {short}")
    if len(QUESTIONS) != 35:
        problems.append(f"  {len(QUESTIONS)} questions (want 35)")
    for q in QUESTIONS:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  malformed '{q['q'][:40]}'")
    if "ERPNext" in json.dumps({"l": LESSONS, "q": QUESTIONS}):
        problems.append("  ERPNext branding leakage")
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    bank = rebalance(list(QUESTIONS))
    dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
    if max(dist.values()) > 10:
        print(f"ABORT — spread failed: {dist}")
        sys.exit(1)

    total = sum(len(l["html"]) for l in LESSONS)
    print(f"POS 2 v2: 10 chapters ({total:,} chars, min {min(len(l['html']) for l in LESSONS):,}), bank {len(bank)}, spread {dist}")

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    data["pos_profile"]["lessons"] = LESSONS
    data["pos_profile"]["questions"] = bank
    data["pos_profile"]["desc"] = "The Point of Sale Profile in full: the ten groundwork records and the back-office test sale, items/prices/tax with the one-template rule, the Setup tab, Discount Mode and the override machinery, Payments & Returns with lay-by and staff purchase wiring, the Gift Vouchers tab and its offline policy, Integrations, the user table's access boxes, and the Power Approver table — with Okelewo's three profiles built as the worked example."
    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.153.0"', '"3.154.0"'))
    print("  data: POS 2 lessons + bank REPLACED (style v2)")
    print("wrote __version__ -> 3.154.0")


if __name__ == "__main__":
    main()
